const items = $input.all();
const escape = (value) => String(value ?? '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;');

const limit = 20;
const sliced = items.slice(0, limit);
const rows = sliced.map((item) => {
  const title = escape(item.json.title || item.json.isoDate || '(no title)');
  const link = String(item.json.link || item.json.guid || '').trim();
  const safeLink = escape(link);
  const date = escape(item.json.isoDate || item.json.pubDate || '');
  const dateBit = date ? ` <small>(${date})</small>` : '';
  if (link) {
    return `<li><a href="${safeLink}">${title}</a>${dateBit}</li>`;
  }
  return `<li>${title}${dateBit}</li>`;
});

const count = rows.length;
const html = count
  ? `<p>${count} item(s) from the feed (max ${limit}).</p><ul>${rows.join('')}</ul>`
  : '<p>The feed returned no items in this run.</p>';

return [{ json: { count, html, feedUrl: 'https://example.com/feed.xml' } }];
